def turan_edges(k, r):
    q = k // r
    s = k % r
    return (k * (k - 1) // 2) - s * (q * (q + 1) // 2) - (r - s) * (q * (q - 1) // 2)

N = 1000
S = 2014
r = 143

for k in range(1, N + 1):
    edges = turan_edges(k, r)
    limit = (N * k**2) / S
    if edges > limit:
        print(f"k={k}, edges={edges}, limit={limit}")
else:
    print("All conditions satisfied.")

print(f"Turan edges for N=1000, r=143: {turan_edges(1000, 143)}")

